def compute_payload_hash(event_data: dict) -> str:
    """Compute the SHA-256 hash of the event payload for verification."""
    payload_str = json.dumps(event_data, sort_keys=True)
    return hashlib.sha256(payload_str.encode()).hexdigest()


def count_audit_entries(db_path: str) -> int:
    """Count the number of entries in the audit_log table."""
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute("SELECT COUNT(*) FROM audit_log")
    count = cursor.fetchone()[0]
    conn.close()
    return count


def get_audit_entry(db_path: str, event_id: str) -> dict:
    """Retrieve a specific audit entry by event_id."""
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute(
        "SELECT event_id, timestamp, sender_id, receiver_id, action, "
        "payload_hash, metadata FROM audit_log WHERE event_id = ?",
        (event_id,)
    )
    row = cursor.fetchone()
    conn.close()
    if row:
        return {
            "event_id": row[0],
            "timestamp": row[1],
            "sender_id": row[2],
            "receiver_id": row[3],
            "action": row[4],
            "payload_hash": row[5],
            "metadata": row[6]
        }
    return None


