class TestImmutability:
    """Verify that audit logs cannot be modified or deleted."""

    def test_prevent_update_trigger(self, audit_logger, sample_event, temp_db_path):
        """UPDATE operations on audit_log should be rejected."""
        event_id = audit_logger.log_event(**sample_event)
        conn = sqlite3.connect(temp_db_path)
        cursor = conn.cursor()
        with pytest.raises(sqlite3.OperationalError, match="cannot modify"):
            cursor.execute(
                "UPDATE audit_log SET action = 'MODIFIED' WHERE event_id = ?",
                (event_id,)
            )
        conn.close()

    def test_prevent_delete_trigger(self, audit_logger, sample_event, temp_db_path):
        """DELETE operations on audit_log should be rejected."""
        event_id = audit_logger.log_event(**sample_event)
        conn = sqlite3.connect(temp_db_path)
        cursor = conn.cursor()
        with pytest.raises(sqlite3.OperationalError, match="cannot delete"):
            cursor.execute(
                "DELETE FROM audit_log WHERE event_id = ?",
                (event_id,)
            )
        conn.close()

    def test_prevent_drop_table(self, audit_logger, temp_db_path):
        """DROP TABLE operations should be rejected."""
        conn = sqlite3.connect(temp_db_path)
        cursor = conn.cursor()
        with pytest.raises(sqlite3.OperationalError):
            cursor.execute("DROP TABLE audit_log")
        conn.close()

    def test_immutability_after_multiple_events(self, audit_logger, sample_event, temp_db_path):
        """Immutability should hold after multiple events are logged."""
        for i in range(5):
            event = sample_event.copy()
            event["metadata"] = {"index": i}
            audit_logger.log_event(**event)

        conn = sqlite3.connect(temp_db_path)
        cursor = conn.cursor()
        with pytest.raises(sqlite3.OperationalError, match="cannot modify"):
            cursor.execute("UPDATE audit_log SET action = 'MASS_MODIFY'")
        conn.close()


