class TestIntegrity:
    """Verify payload hash integrity and tamper detection."""

    def test_verify_integrity_valid(self, audit_logger, sample_event):
        """Integrity check should pass for unmodified events."""
        event_id = audit_logger.log_event(**sample_event)
        assert audit_logger.verify_integrity(event_id) is True

    def test_verify_integrity_invalid_event_id(self, audit_logger):
        """Non-existent event ID should return False."""
        assert audit_logger.verify_integrity("non-existent-id") is False

    def test_verify_integrity_tampered_payload(self, audit_logger, sample_event, temp_db_path):
        """Integrity check should fail if payload hash is tampered."""
        event_id = audit_logger.log_event(**sample_event)
        # Directly tamper with the payload_hash in the database
        conn = sqlite3.connect(temp_db_path)
        cursor = conn.cursor()
        # Bypass trigger by using PRAGMA writable_schema (for testing only)
        cursor.execute("PRAGMA writable_schema=ON")
        cursor.execute(
            "UPDATE audit_log SET payload_hash = 'tampered_hash' WHERE event_id = ?",
            (event_id,)
        )
        conn.commit()
        conn.close()
        assert audit_logger.verify_integrity(event_id) is False

    def test_verify_all_integrity(self, audit_logger, sample_event):
        """Verify integrity of all events in the log."""
        for i in range(3):
            event = sample_event.copy()
            event["metadata"] = {"index": i}
            audit_logger.log_event(**event)
        results = audit_logger.verify_all_integrity()
        assert all(results.values())

    def test_verify_all_integrity_with_tampered(self, audit_logger, sample_event, temp_db_path):
        """verify_all_integrity should detect tampered events."""
        event_ids = []
        for i in range(3):
            event = sample_event.copy()
            event["metadata"] = {"index": i}
            event_id = audit_logger.log_event(**event)
            event_ids.append(event_id)

        # Tamper with the second event
        conn = sqlite3.connect(temp_db_path)
        cursor = conn.cursor()
        cursor.execute("PRAGMA writable_schema=ON")
        cursor.execute(
            "UPDATE audit_log SET payload_hash = 'tampered' WHERE event_id = ?",
            (event_ids[1],)
        )
        conn.commit()
        conn.close()

        results = audit_logger.verify_all_integrity()
        assert results[event_ids[0]] is True
        assert results[event_ids[1]] is False
        assert results[event_ids[2]] is True


