class TestConcurrency:
    """Verify thread safety and concurrent access handling."""

    def test_concurrent_logging(self, audit_logger, sample_event):
        """Multiple threads should be able to log simultaneously."""
        num_threads = 10
        events_per_thread = 10
        errors = []

        def log_events(thread_id):
            for i in range(events_per_thread):
                try:
                    event = sample_event.copy()
                    event["metadata"] = {"thread": thread_id, "index": i}
                    audit_logger.log_event(**event)
                except Exception as e:
                    errors.append(e)

        threads = []
        for t in range(num_threads):
            thread = threading.Thread(target=log_events, args=(t,))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()

        assert len(errors) == 0
        assert count_audit_entries(audit_logger.db_path) == num_threads * events_per_thread

    def test_concurrent_read_write(self, audit_logger, sample_event, temp_db_path):
        """Concurrent reads and writes should not cause deadlocks."""
        num_operations = 50
        errors = []

        def writer():
            for i in range(num_operations):
                try:
                    event = sample_event.copy()
                    event["metadata"] = {"index": i}
                    audit_logger.log_event(**event)
                except Exception as e:
                    errors.append(e)

        def reader():
            for _ in range(num_operations):
                try:
                    audit_logger.verify_all_integrity()
                except Exception as e:
                    errors.append(e)

        writer_thread = threading.Thread(target=writer)
        reader_thread = threading.Thread(target=reader)

        writer_thread.start()
        reader_thread.start()

        writer_thread.join()
        reader_thread.join()

        assert len(errors) == 0

    def test_concurrent_same_event_id(self, audit_logger, sample_event):
        """Concurrent attempts to log the same event ID should be handled."""
        # This tests the UNIQUE constraint on event_id
        import uuid
        fixed_event_id = str(uuid.uuid4())
        errors = []

        def attempt_log():
            try:
                audit_logger.log_event(
                    sender_id=sample_event["sender_id"],
                    receiver_id=sample_event["receiver_id"],
                    action=sample_event["action"],
                    metadata=sample_event["metadata"],
                    event_id=fixed_event_id
                )
            except Exception as e:
                errors.append(e)

        threads = [threading.Thread(target=attempt_log) for _ in range(5)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        # Only one should succeed, others should fail
        assert len(errors) == 4


