# =============================================================================
# Test Suite: Property-Based Testing (using Hypothesis)
# =============================================================================

class TestPropertyBased:
    """Property-based tests for invariant verification."""

    def test_event_id_uniqueness_property(self, audit_logger, sample_event):
        """All event IDs should be unique."""
        event_ids = set()
        for i in range(100):
            event = sample_event.copy()
            event["metadata"] = {"index": i}
            event_id = audit_logger.log_event(**event)
            assert event_id not in event_ids
            event_ids.add(event_id)

    def test_timestamp_monotonic_property(self, audit_logger, sample_event):
        """Timestamps should be monotonically increasing."""
        previous_timestamp = None
        for i in range(100):
            event = sample_event.copy()
            event["metadata"] = {"index": i}
            event_id = audit_logger.log_event(**event)
            entry = get_audit_entry(audit_logger.db_path, event_id)
            current_timestamp = entry["timestamp"]
            if previous_timestamp:
                assert current_timestamp >= previous_timestamp
            previous_timestamp = current_timestamp

    def test_payload_hash_consistency_property(self, audit_logger, sample_event):
        """Same input should produce same payload hash."""
        event_id1 = audit_logger.log_event(**sample_event)
        event_id2 = audit_logger.log_event(**sample_event)
        entry1 = get_audit_entry(audit_logger.db_path, event_id1)
        entry2 = get_audit_entry(audit_logger.db_path, event_id2)
        assert entry1["payload_hash"] == entry2["payload_hash"]

    def test_immutability_after_verify_property(self, audit_logger, sample_event):
        """Verification should not modify the log."""
        event_id = audit_logger.log_event(**sample_event)
        original_entry = get_audit_entry(audit_logger.db_path, event_id)
        audit_logger.verify_integrity(event_id)
        current_entry = get_audit_entry(audit_logger.db_path, event_id)
        assert original_entry == current_entry


